   for short in[SqliteDatabaseLimits{max_rows:limits.max_rows-1,..limits},SqliteDatabaseLimits{max_value_bytes:limits.max_value_bytes-1,..limits},SqliteDatabaseLimits{max_schema_bytes:limits.max_schema_bytes-1,..limits},SqliteDatabaseLimits{max_tables:11,..limits},SqliteDatabaseLimits{max_columns:34,..limits}]{assert!(io_export_sqlite_snapshot(&dialect,&source,encoding,short,&mut |_|true).await.is_err());assert!(io_import_sqlite_snapshot::<SemioKitSnapshot>(&dialect,&file,short,&mut |_|true).await.is_err());}
